insert into public.verse_geography(verse_id,place_id,relationship_type,resolution_tier,is_inferred,confidence_level,evidence_ref,evidence_explanation,establishing_passage_id,source_id)
select vr.id,pl.id,v.relationship_type,v.resolution_tier::smallint,v.is_inferred,v.confidence_level,v.evidence_ref,v.evidence_explanation,null::bigint,s.id
from (values
(43,4,3,'openbible:a149f13','travel_origin',1,false,'established','John 4:3','Jesus leaves Judea (travel origin) and departs again for Galilee.',null,'curated_narrative_geography'),
(43,4,3,'openbible:a9cf1e8','travel_destination',1,false,'established','John 4:3','Galilee is the destination of Jesus'' journey from Judea through Samaria.',null,'curated_narrative_geography'),
(44,18,1,'openbible:a1fe6e7','travel_origin',1,false,'established','Acts 18:1','Paul departs from Athens (travel origin) and goes to Corinth.',null,'curated_narrative_geography'),
(44,18,1,'openbible:a6f437a','travel_destination',1,false,'established','Acts 18:1','Paul arrives in Corinth (travel destination) after leaving Athens.',null,'curated_narrative_geography'),
(1,28,10,'openbible:ad2f6c2','travel_origin',1,false,'established','Genesis 28:10','Jacob sets out from Beersheba (travel origin) toward Haran.',null,'curated_narrative_geography'),
(1,28,10,'openbible:a6d9af3','travel_destination',1,false,'established','Genesis 28:10','Jacob travels toward Haran (travel destination).',null,'curated_narrative_geography')
) as v(book,chapter,verse,place_key,relationship_type,resolution_tier,is_inferred,confidence_level,evidence_ref,evidence_explanation,passage_key,source_key)
join public.verses vr on vr.book = v.book::smallint and vr.chapter = v.chapter::smallint and vr.verse_nr = v.verse::smallint
join public.places pl on pl.place_key = v.place_key
join public.geography_sources s on s.source_key = v.source_key
on conflict(verse_id,place_id,relationship_type) do nothing;
